    ? segmentSpeechText(req.text).map((segment) => ({
        ...req,
        text: segment.text,
        sourceOffset: (req.sourceOffset ?? 0) + segment.start,
      }))
    : [req];
  await speakQueue(segments, {
    ownerId: segments.length > 1 ? req.id : undefined,
  });
}

