import { Slot, component$, useStyles$ } from "@qwik.dev/core";
import type { Persona } from "../../types";
import { renderMarkdown } from "../../utils/markdown";
import { openLiveVoice } from "../../utils/live-voice-workspace";
import { SpeakButton } from "../ui/speak-button";
import { PersonaPortrait } from "./persona-portrait";
import styles from "./persona-card.css?inline";

export interface PersonaCardProps {
  persona: Persona;
  /** Which sample note to show as the editor's calling card. */
  sampleIndex?: number;
}

/** Markdown marks are for the eye; read aloud, they are noise. */
function spoken(text: string): string {
  return text.replace(/[*_`]/g, "").replace(/[«»]/g, "");
}

/**
 * An editor's calling card: the engraved figure on their own colour plate,
 * and one note in their hand, so a writer learns to recognise the voice on
 * the page before they meet it in the margin. Edit and order controls go
 * in the default slot.
 */
export const PersonaCard = component$<PersonaCardProps>((props) => {
  useStyles$(styles);
  const p = props.persona;
  const sample =
    p.sampleLines?.[props.sampleIndex ?? 0] ?? p.sampleLines?.[0] ?? "";
  const speechId = `persona-card-${p.id}`;
  return (
    <article
      class="persona-card"
      style={{ "--pp-color": p.color }}
      aria-labelledby={`${speechId}-name`}
    >
      <div class="persona-card__plate">
        <span class="persona-card__suit" aria-hidden="true">
          {p.icon}
        </span>
        <PersonaPortrait
          personaId={p.id}
          name={p.name}
          color={p.color}
          framing="figure"
          size={208}
          class="persona-card__figure"
        />
      </div>

      <div class="persona-card__body">
        <header class="persona-card__head">
          <p class="persona-card__role">{p.role}</p>
          <h3 class="persona-card__name" id={`${speechId}-name`}>
            {p.name}
          </h3>
          <p class="persona-card__description">{p.description}</p>
        </header>

        {sample && (
          <figure class="persona-card__sample">
            <figcaption>In the margin</figcaption>
            <div
              class="persona-card__note comment-markdown"
              data-speech-id={speechId}
              dangerouslySetInnerHTML={renderMarkdown(sample)}
            />
          </figure>
        )}

        <footer class="persona-card__actions">
          {sample && (
            <span class="persona-card__hear">
              <SpeakButton
                id={speechId}
                text={spoken(sample)}
                voice={p.speechVoice}
                voices={p.speechVoices}
                instructions={p.voice}
                label={p.name}
              />
              Hear {p.name.split(" ").at(-1)}
            </span>
          )}
          <button
            type="button"
            class="persona-card__talk"
            onClick$={() => openLiveVoice(p.name)}
          >
            <svg
              width="14"
              height="14"
              viewBox="0 0 24 24"
              fill="none"
              stroke="currentColor"
              stroke-width="2"
              stroke-linecap="round"
              aria-hidden="true"
            >
              <rect x="9" y="3" width="6" height="11" rx="3" />
              <path d="M5 11a7 7 0 0 0 14 0M12 18v3" />
            </svg>
            Talk it through
          </button>
          <span class="persona-card__controls">
            <Slot />
          </span>
        </footer>
      </div>
    </article>
  );
});

.persona-card {
  position: relative;
  display: grid;
  grid-template-columns: 13rem minmax(0, 1fr);
  min-width: 0;
  overflow: hidden;
  color: var(--color-ink);
  background: var(--color-paper-soft, var(--color-paper));
  border: 1px solid color-mix(in srgb, var(--pp-color) 35%, var(--color-paper-3));
  border-radius: 6px;
  box-shadow: 0 1px 0 color-mix(in srgb, var(--pp-color) 30%, transparent);
}

/* The editor's own colour, inked like a printer's plate. */
.persona-card__plate {
  position: relative;
  display: flex;
  align-items: flex-end;
  justify-content: center;
  min-height: 15rem;
  overflow: hidden;
  background:
    radial-gradient(
      circle at 50% 30%,
      color-mix(in srgb, var(--pp-color) 22%, var(--color-paper)) 0 38%,
      transparent 72%
    ),
    repeating-linear-gradient(
      -45deg,
      color-mix(in srgb, var(--pp-color) 10%, transparent) 0 1px,
      transparent 1px 7px
    ),
    color-mix(in srgb, var(--pp-color) 46%, var(--color-paper));
}

.persona-card__suit {
  position: absolute;
  top: 0.4rem;
  left: 0.75rem;
  color: color-mix(in srgb, var(--pp-color) 75%, var(--color-ink));
  font: 400 3.25rem/1 var(--font-display);
  opacity: 0.35;
}

.persona-card__figure {
  margin-bottom: -2.25rem;
  transition: transform 500ms cubic-bezier(0.2, 0.7, 0.2, 1);
}

.persona-card:hover .persona-card__figure,
.persona-card:focus-within .persona-card__figure {
  transform: translateY(-0.4rem);
}

.persona-card__body {
  display: flex;
  flex-direction: column;
  gap: 0.9rem;
  min-width: 0;
  padding: 1.1rem 1.25rem 1rem;
}

.persona-card__role {
  margin: 0;
  color: color-mix(in srgb, var(--pp-color) 70%, var(--color-ink));
  font: 400 0.68rem/1.3 var(--font-typewriter);
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.persona-card__name {
  margin: 0.2rem 0 0;
  font: 700 1.45rem/1.15 var(--font-display);
}

.persona-card__description {
  margin: 0.45rem 0 0;
  color: var(--color-ink-light);
  font: 400 0.92rem/1.55 var(--font-serif);
}

/* One note in their hand: a slip pinned in the margin. */
.persona-card__sample {
  margin: 0;
  padding: 0.7rem 0.9rem 0.75rem;
  background: var(--color-paper);
  border-left: 3px solid var(--pp-color);
  box-shadow: 0 6px 14px -12px rgb(0 0 0 / 0.5);
}

.persona-card__sample figcaption {
  margin-bottom: 0.35rem;
  color: var(--color-ink-muted);
  font: 400 0.6rem/1 var(--font-typewriter);
  letter-spacing: 0.16em;
  text-transform: uppercase;
}

.persona-card__note {
  font: 400 0.95rem/1.55 var(--font-serif);
}

.persona-card__note p {
  margin: 0;
}

.persona-card__note strong {
  color: color-mix(in srgb, var(--pp-color) 80%, var(--color-ink));
}

.persona-card__actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.5rem 0.9rem;
  margin-top: auto;
  font: 400 0.7rem/1 var(--font-typewriter);
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.persona-card__hear {
  display: inline-flex;
  align-items: center;
  gap: 0.2rem;
  color: var(--color-ink-light);
}

.persona-card__talk {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  padding: 0.5rem 0.8rem;
  color: var(--color-paper);
  background: color-mix(in srgb, var(--pp-color) 82%, var(--color-ink));
  border-radius: 999px;
  font: inherit;
  letter-spacing: inherit;
  text-transform: inherit;
  transition: background 160ms ease;
}

.persona-card__talk:hover {
  background: color-mix(in srgb, var(--pp-color) 60%, var(--color-ink));
}

.persona-card__talk:focus-visible {
  outline: 2px solid var(--pp-color);
  outline-offset: 3px;
}

.persona-card__controls {
  display: inline-flex;
  align-items: center;
  gap: 0.75rem;
  margin-left: auto;
}

.persona-card__controls:empty {
  display: none;
}

@media (max-width: 34rem) {
  .persona-card {
    grid-template-columns: minmax(0, 1fr);
  }
  .persona-card__plate {
    min-height: 11rem;
  }
  .persona-card__figure {
    width: 9.5rem !important;
    flex-basis: 9.5rem !important;
    margin-bottom: -4.5rem;
  }
}

@media (prefers-reduced-motion: reduce) {
  .persona-card__figure {
    transition: none;
  }
}

