import {
  $,
  component$,
  useSignal,
  useStore,
  useVisibleTask$,
  useStyles$,
} from "@qwik.dev/core";
import { makeFunctionReference } from "convex/server";
import { useAuth } from "../../utils/auth-context";
import { useConvexClient } from "../../utils/convex-context";
import { PERSONAS } from "../../utils/personas";
import { loadPersonasFromIdb } from "../../utils/idb";
import { LIVE_OPEN_EVENT } from "../../utils/live-voice-workspace";
import {
  endLiveVoice,
  liveVoiceLevels,
  liveVoiceState,
  LIVE_STATE_EVENT,
  muteLiveVoice,
  reviewVoiceEdit,
  startLiveVoice,
} from "../../utils/live-voice";
import { PersonaPortrait } from "../personas/persona-portrait";
import styles from "./live-voice-desk.css?inline";

type Access = {
  eligible: boolean;
  welcome: boolean;
  availableMicros: number;
  sessionBudgetMicros: number;
  consentGranted: boolean;
};

type CastMember = {
  id: string;
  name: string;
  role: string;
  color: string;
};

const toCast = (p: CastMember): CastMember => ({
  id: p.id,
  name: p.name,
  role: p.role,
  color: p.color,
});

const MIC_ICON = (
  <svg
    width="20"
    height="20"
    viewBox="0 0 24 24"
    fill="none"
    stroke="currentColor"
    stroke-width="2"
    stroke-linecap="round"
    aria-hidden="true"
  >
    <rect x="9" y="3" width="6" height="11" rx="3" />
    <path d="M5 11a7 7 0 0 0 14 0M12 18v3" />
  </svg>
);

/**
 * A conversation with one editor, face to face.
 *
 * The editor's portrait is the whole interface: it opens its mouth in time
 * with the voice you hear, and a halo around it follows your microphone, so
 * you can tell who is talking without reading a status line. Everything that
 * is not the conversation — credit, consent, fine print — stays folded
 * until it is needed.
 */
export const LiveVoiceDesk = component$(() => {
  useStyles$(styles);
  const client = useConvexClient();
  const auth = useAuth();
  const live = useStore(liveVoiceState());
  const stage = useSignal<HTMLElement>();
  const ui = useStore({
    open: false,
    compact: false,
    author: "Le Lecteur",
    passage: "",
    cast: PERSONAS.map(toCast),
    access: null as Access | null,
    loading: false,
    error: "",
    consent: false,
    elapsed: 0,
    transcript: false,
  });
  const refresh = $(async () => {
    if (!client.value || !auth.value.user) return;
    ui.loading = true;
    ui.error = "";
    try {
      ui.access = await client.value.action(
        makeFunctionReference<"action", Record<string, never>, Access>(
          "liveVoice:access",
        ),
        {},
      );
      ui.consent = ui.access.consentGranted;
    } catch {
      ui.error =
        "Could not check Live access. Retry, or check your account in Settings.";
    } finally {
      ui.loading = false;
    }
  });
  // eslint-disable-next-line qwik/no-use-visible-task
  useVisibleTask$(
    ({ track }) => {
      track(() => auth.value.user?.id);
      endLiveVoice();
      ui.access = null;
      ui.consent = false;
      ui.open = false;
    },
    { strategy: "document-ready" },
  );
  // eslint-disable-next-line qwik/no-use-visible-task
  useVisibleTask$(
    ({ cleanup }) => {
      const sync = () => {
        const wasActive = !["idle", "error"].includes(live.status);
        Object.assign(live, liveVoiceState());
        if (wasActive && ["idle", "error"].includes(live.status))
          void refresh();
      };
      const open = async (event: Event) => {
        const detail = (
          event as CustomEvent<{ author?: string; passage?: string }>
        ).detail;
        if (["idle", "error"].includes(live.status)) {
          const cast = await loadPersonasFromIdb().catch(() => null);
          if (cast?.length) ui.cast = cast.map(toCast);
          ui.author =
            ui.cast.find(
              (p) => p.name === detail?.author || p.id === detail?.author,
            )?.name ?? "Le Lecteur";
          if (!ui.cast.some((p) => p.name === ui.author))
            ui.author = ui.cast[0]?.name ?? "Le Lecteur";
          ui.passage = detail?.passage ?? "";
          ui.access = null;
        }
        ui.open = true;
        ui.compact = false;
        await refresh();
        document.getElementById("live-voice-heading")?.focus();
      };
      const tick = setInterval(() => {
        ui.elapsed = live.startedAt
          ? Math.floor((Date.now() - live.startedAt) / 1000)
          : 0;
      }, 1000);
      // Levels go straight onto the stage's custom properties each frame;
      // routing 60 updates a second through the store would re-render the
      // desk for nothing. Smoothed so the jaw eases rather than flickers.
      let frame = 0;
      let voice = 0;
      let mic = 0;
      const animate = () => {
        frame = requestAnimationFrame(animate);
        const el = stage.value;
        if (!el) return;
        const { input, output } = liveVoiceLevels();
        voice += (output - voice) * (output > voice ? 0.55 : 0.2);
        mic += (input - mic) * (input > mic ? 0.5 : 0.12);
        el.style.setProperty("--pp-level", voice.toFixed(3));
        el.style.setProperty("--mic-level", mic.toFixed(3));
      };
      frame = requestAnimationFrame(animate);
      window.addEventListener(LIVE_STATE_EVENT, sync);
      window.addEventListener(LIVE_OPEN_EVENT, open);
      cleanup(() => {
        cancelAnimationFrame(frame);
        clearInterval(tick);
        window.removeEventListener(LIVE_STATE_EVENT, sync);
        window.removeEventListener(LIVE_OPEN_EVENT, open);
        endLiveVoice();
      });
    },
    { strategy: "document-ready" },
  );

  const active = !["idle", "error"].includes(live.status);
  const connected = ["listening", "speaking"].includes(live.status);
  const author = active ? live.author : ui.author;
  const speaker = ui.cast.find((p) => p.name === author) ?? ui.cast[0];
  const firstName = (speaker?.name ?? author).split(" ").at(-1);
  const signedIn = Boolean(auth.value.user);
  const access = ui.access;
  const affordable = !!access && access.availableMicros >= 500_000;
  const canStart =
    signedIn && !!access?.eligible && affordable && ui.consent && !ui.loading;
  const status =
    live.status === "connecting"
      ? "Connecting…"
      : live.status === "closing"
        ? "Wrapping up…"
        : live.status === "speaking"
          ? `${firstName} is speaking — just talk to interrupt`
          : live.status === "listening"
            ? live.muted
              ? "You’re muted"
              : "Listening…"
            : live.finalized
              ? "Conversation ended"
              : `Talk your draft through with ${firstName}`;
  const lastUser = [...live.turns].reverse().find((t) => t.role === "user");
  const lastEditor = [...live.turns]
    .reverse()
    .find((t) => t.role === "assistant");
  const clock = `${Math.floor(ui.elapsed / 60)}:${String(ui.elapsed % 60).padStart(2, "0")}`;

  return (
    // Keep the host mounted: returning null reruns visible tasks on close,
    // whose voice-state reset would schedule another render indefinitely.
    <aside
      class={["live-voice-desk", { "is-compact": ui.compact }]}
      hidden={!ui.open}
      aria-label="Live voice desk"
      data-status={live.status}
      style={{ "--pp-color": speaker?.color }}
    >
      <header class="lvd-bar">
        <h2 id="live-voice-heading" tabIndex={-1}>
          <span class="lvd-live-dot" aria-hidden="true" />
          {active ? "Live" : "Voice"}
          {active && <span class="lvd-clock">{clock}</span>}
        </h2>
        <button
          type="button"
          class="lvd-icon-btn"
          aria-label={ui.compact ? "Expand voice desk" : "Minimize voice desk"}
          onClick$={() => {
            ui.compact = !ui.compact;
          }}
        >
          {ui.compact ? "↗" : "−"}
        </button>
        {!active && (
          <button
            type="button"
            class="lvd-icon-btn"
            aria-label="Close voice desk"
            onClick$={() => {
              ui.open = false;
            }}
          >
            ×
          </button>
        )}
      </header>

      <section
        ref={stage}
        class="lvd-stage"
        data-muted={live.muted ? "true" : undefined}
      >
        <div class="lvd-face">
          <span class="lvd-halo" aria-hidden="true" />
          <PersonaPortrait
            personaId={speaker?.id}
            name={speaker?.name ?? author}
            color={speaker?.color}
            size={ui.compact ? 56 : 148}
            speaking={connected ? "live" : undefined}
          />
        </div>
        {!ui.compact && (
          <div class="lvd-identity">
            <p class="lvd-name">{speaker?.name ?? author}</p>
            <p class="lvd-role">{speaker?.role}</p>
          </div>
        )}
        <p class="lvd-status" role="status">
          {live.working ? "Working on it…" : status}
        </p>
      </section>

      {!ui.compact && (
        <div class="lvd-body">
          {!active && (
            <div
              class="lvd-cast"
              role="radiogroup"
              aria-label="Choose who to talk with"
            >
              {ui.cast.map((p) => (
                <button
                  key={p.id}
                  type="button"
                  role="radio"
                  class="lvd-cast-pick"
                  aria-checked={p.name === ui.author}
                  aria-label={`${p.name}, ${p.role}`}
                  title={`${p.name} · ${p.role}`}
                  style={{ "--pp-color": p.color }}
                  onClick$={() => {
                    ui.author = p.name;
                  }}
                >
                  <PersonaPortrait
                    personaId={p.id}
                    name={p.name}
                    color={p.color}
                    size={40}
                  />
                </button>
              ))}
            </div>
          )}

          {ui.passage && !active && (
            <blockquote class="lvd-context">
              <span>About this note</span>
              {ui.passage.slice(0, 220)}
              {ui.passage.length > 220 ? "…" : ""}
            </blockquote>
          )}

          {(active || live.turns.length > 0) && (
            <div class="lvd-captions" aria-label="Conversation captions">
              {ui.transcript ? (
                <ol class="lvd-transcript">
                  {live.turns.map((turn, i) => (
                    <li key={i} data-role={turn.role}>
                      <span>{turn.role === "user" ? "You" : firstName}</span>
                      {turn.text.trim()}
                    </li>
                  ))}
                </ol>
              ) : (
                <>
                  {lastEditor && (
                    <p class="lvd-caption lvd-caption--editor">
                      {lastEditor.text.trim().slice(-320)}
                    </p>
                  )}
                  {lastUser && (
                    <p class="lvd-caption lvd-caption--you">
                      <span>You</span>
                      {lastUser.text.trim().slice(-200)}
                    </p>
                  )}
                  {!lastEditor && !lastUser && (
                    <p class="lvd-caption lvd-caption--hint">
                      Say hello — or ask about the passage you’re stuck on.
                    </p>
                  )}
                </>
              )}
              {live.turns.length > 2 && (
                <button
                  type="button"
                  class="lvd-link"
                  onClick$={() => {
                    ui.transcript = !ui.transcript;
                  }}
                >
                  {ui.transcript ? "Latest only" : "Full transcript"}
                </button>
              )}
            </div>
          )}

          {live.notice && (
            <p class="lvd-notice" role="status">
              {live.notice}
            </p>
          )}

          {live.pending && (
            <section class="lvd-edit" aria-label="Proposed draft edit">
              <p class="lvd-edit-kicker">
                {live.pending.kind === "append"
                  ? `${firstName} suggests adding`
                  : `${firstName} suggests`}
              </p>
              {live.pending.original && <del>{live.pending.original}</del>}
              <ins>{live.pending.text || "Remove this passage"}</ins>
              <div class="lvd-edit-actions">
                <button
                  type="button"
                  class="lvd-pill lvd-pill--solid"
                  disabled={live.working}
                  onClick$={() => reviewVoiceEdit(true)}
                >
                  Apply edit
                </button>
                <button
                  type="button"
                  class="lvd-pill"
                  disabled={live.working}
                  onClick$={() => reviewVoiceEdit(false)}
                >
                  Discard
                </button>
                <span>or just say so</span>
              </div>
            </section>
          )}

          {live.sources.length > 0 && (
            <ul class="lvd-sources">
              {live.sources.map((source) => (
                <li key={source.url}>
                  <a
                    href={source.url}
                    target="_blank"
                    rel="noopener noreferrer"
                  >
                    {source.title} ↗
                  </a>
                  <p>{source.snippet.slice(0, 180)}</p>
                </li>
              ))}
            </ul>
          )}

          {(live.error || ui.error) && (
            <p role="alert" class="lvd-error">
              {live.error || ui.error}
            </p>
          )}

          {!active && (
            <div class="lvd-gate">
              {!signedIn ? (
                <p>
                  <a href="/signin/">Sign in</a> to talk with your editors.
                  New accounts start with welcome credit.
                </p>
              ) : ui.loading && !access ? (
                <p>Checking your credit…</p>
              ) : !access ? (
                <button type="button" class="lvd-link" onClick$={refresh}>
                  Check voice access
                </button>
              ) : !access.eligible ? (
                <p>
                  Voice is part of Pro. <a href="/pricing/">See plans</a>
                </p>
              ) : !affordable ? (
                <p>
                  ${(access.availableMicros / 1_000_000).toFixed(2)} left — a
                  conversation needs $0.50. <a href="/pricing/">Add credit</a>
                </p>
              ) : (
                !access.consentGranted && (
                  <label class="lvd-consent">
                    <input
                      type="checkbox"
                      checked={ui.consent}
                      onChange$={(_, element) => {
                        ui.consent = element.checked;
                      }}
                    />
                    <span>
                      Let the voice provider process my microphone and the
                      draft I share, through Not Organic.
                    </span>
                  </label>
                )
              )}
              {access && (
                <details class="lvd-fine">
                  <summary>
                    ${(access.availableMicros / 1_000_000).toFixed(2)}{" "}
                    {access.welcome ? "welcome credit" : "in your wallet"} ·
                    how billing works
                  </summary>
                  <p>
                    Up to $0.50 is reserved per conversation; app requests use
                    up to $0.05 each on top. Unused credit is released when the
                    session settles. GPT Live voice, speaking from your
                    editor’s perspective. Audio isn’t recorded in Twyne;
                    captions stay in this session.
                  </p>
                </details>
              )}
            </div>
          )}
        </div>
      )}

      <footer class="lvd-controls">
        {active ? (
          <>
            <button
              type="button"
              class="lvd-round"
              disabled={!connected}
              aria-pressed={live.muted}
              aria-label={live.muted ? "Unmute microphone" : "Mute microphone"}
              title={live.muted ? "Unmute" : "Mute"}
              onClick$={() => muteLiveVoice()}
            >
              {MIC_ICON}
              {live.muted && <span class="lvd-slash" aria-hidden="true" />}
            </button>
            <button
              type="button"
              class="lvd-end"
              disabled={live.status === "closing"}
              onClick$={() => {
                endLiveVoice();
              }}
            >
              {live.status === "connecting" ? "Cancel" : "End"}
            </button>
          </>
        ) : (
          <button
            type="button"
            class="lvd-start"
            disabled={!canStart}
            onClick$={async () => {
              if (!client.value) return;
              await startLiveVoice(
                client.value,
                ui.author,
                ui.passage,
                !ui.access?.consentGranted && ui.consent,
              );
            }}
          >
            {MIC_ICON}
            {live.finalized ? "Talk again" : "Start talking"}
          </button>
        )}
      </footer>
    </aside>
  );
});

@property --mic-level {
  syntax: "<number>";
  inherits: true;
  initial-value: 0;
}

.live-voice-desk {
  --lvd-tint: color-mix(in srgb, var(--pp-color, var(--color-vermilion)) 14%, var(--color-paper));
  position: fixed;
  z-index: var(--z-modal, 100);
  right: 1rem;
  bottom: 1rem;
  width: min(360px, calc(100vw - 2rem));
  max-height: calc(100dvh - 2rem);
  display: flex;
  flex-direction: column;
  color: var(--color-ink);
  background: var(--color-paper);
  border: 1px solid color-mix(in srgb, var(--pp-color) 30%, var(--color-paper-3));
  border-radius: 22px;
  box-shadow:
    0 24px 48px -24px rgb(0 0 0 / 0.45),
    0 2px 6px -2px rgb(0 0 0 / 0.12);
  overflow: hidden;
  font-family: var(--font-sans);
  font-size: 0.85rem;
  transition: width 260ms cubic-bezier(0.2, 0.7, 0.2, 1);
}
.live-voice-desk[hidden] {
  display: none;
}

/* ── Top bar: a quiet label and the window controls ───────── */
.lvd-bar {
  position: absolute;
  inset: 0 0 auto 0;
  z-index: 2;
  display: flex;
  align-items: center;
  gap: 0.25rem;
  padding: 0.6rem 0.6rem 0 1rem;
}
.lvd-bar h2 {
  flex: 1;
  display: flex;
  align-items: center;
  gap: 0.45rem;
  margin: 0;
  color: color-mix(in srgb, var(--pp-color) 55%, var(--color-ink));
  font: 400 0.65rem/1 var(--font-typewriter);
  letter-spacing: 0.16em;
  text-transform: uppercase;
}
.lvd-bar h2:focus {
  outline: none;
}
.lvd-live-dot {
  width: 0.45rem;
  height: 0.45rem;
  border-radius: 50%;
  background: var(--color-ink-muted);
}
.live-voice-desk:is([data-status="listening"], [data-status="speaking"]) .lvd-live-dot {
  background: var(--color-vermilion);
  animation: lvd-blink 1.6s ease-in-out infinite;
}
.lvd-clock {
  color: var(--color-ink-muted);
  font-variant-numeric: tabular-nums;
  letter-spacing: 0.06em;
}
.lvd-icon-btn {
  display: grid;
  place-items: center;
  width: 1.9rem;
  height: 1.9rem;
  border-radius: 50%;
  color: var(--color-ink-light);
  font-size: 1rem;
  line-height: 1;
}
.lvd-icon-btn:hover {
  background: color-mix(in srgb, var(--pp-color) 16%, transparent);
  color: var(--color-ink);
}

/* ── The stage: the editor's face, large ─────────────────── */
.lvd-stage {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 2.6rem 1.25rem 1.1rem;
  text-align: center;
  background:
    radial-gradient(
      ellipse 80% 70% at 50% 42%,
      color-mix(in srgb, var(--pp-color) 22%, var(--color-paper)) 0%,
      var(--color-paper) 72%
    );
}
.lvd-face {
  position: relative;
  display: grid;
  place-items: center;
  padding: 14px;
}
/* Your voice, as a soft ring breathing around the editor's face. */
.lvd-halo {
  position: absolute;
  inset: 0;
  border-radius: 50%;
  background: radial-gradient(
    circle,
    transparent 58%,
    color-mix(in srgb, var(--pp-color) 40%, transparent) 64%,
    transparent 72%
  );
  opacity: calc(0.15 + var(--mic-level) * 0.85);
  scale: calc(0.92 + var(--mic-level) * 0.16);
  pointer-events: none;
}
.lvd-stage[data-muted] .lvd-halo {
  opacity: 0;
}
.live-voice-desk[data-status="connecting"] .lvd-halo {
  animation: lvd-breathe 1.4s ease-in-out infinite;
}
.lvd-identity {
  margin-top: 0.4rem;
}
.lvd-name {
  margin: 0;
  font: 700 1.2rem/1.2 var(--font-display);
}
.lvd-role {
  margin: 0.15rem 0 0;
  color: color-mix(in srgb, var(--pp-color) 65%, var(--color-ink));
  font: 400 0.68rem/1.3 var(--font-typewriter);
  letter-spacing: 0.12em;
  text-transform: uppercase;
}
.lvd-status {
  margin: 0.65rem 0 0;
  color: var(--color-ink-light);
  font: italic 400 0.92rem/1.4 var(--font-serif);
}

/* ── Body: who to talk to, then the conversation ─────────── */
.lvd-body {
  display: flex;
  flex-direction: column;
  gap: 0.9rem;
  padding: 0 1.1rem 0.9rem;
  overflow: auto;
  overscroll-behavior: contain;
}
.lvd-cast {
  display: flex;
  justify-content: center;
  gap: 0.55rem;
}
.lvd-cast-pick {
  border-radius: 50%;
  opacity: 0.55;
  filter: saturate(0.4);
  transition:
    opacity 160ms ease,
    filter 160ms ease,
    transform 180ms cubic-bezier(0.2, 0.7, 0.2, 1);
}
.lvd-cast-pick:hover {
  opacity: 0.9;
  filter: none;
  transform: translateY(-2px);
}
.lvd-cast-pick[aria-checked="true"] {
  opacity: 1;
  filter: none;
  transform: scale(1.08);
}
.lvd-context {
  margin: 0;
  padding: 0.6rem 0.75rem;
  border-left: 3px solid var(--pp-color);
  background: var(--lvd-tint);
  border-radius: 0 8px 8px 0;
  font: 400 0.88rem/1.45 var(--font-serif);
}
.lvd-context span {
  display: block;
  margin-bottom: 0.2rem;
  color: var(--color-ink-muted);
  font: 400 0.6rem/1 var(--font-typewriter);
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

/* Captions: the latest thing said by each of you, not a log. */
.lvd-captions {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}
.lvd-caption {
  margin: 0;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}
.lvd-caption--editor {
  font: 400 1.02rem/1.5 var(--font-serif);
}
.lvd-caption--you {
  align-self: flex-end;
  max-width: 88%;
  padding: 0.45rem 0.7rem;
  background: var(--color-paper-2);
  border-radius: 12px 12px 4px 12px;
  color: var(--color-ink-light);
  font-size: 0.82rem;
  line-height: 1.4;
}
.lvd-caption--you span,
.lvd-transcript span {
  display: block;
  color: var(--color-ink-muted);
  font: 400 0.58rem/1.2 var(--font-typewriter);
  letter-spacing: 0.14em;
  text-transform: uppercase;
}
.lvd-caption--hint {
  color: var(--color-ink-muted);
  font: italic 400 0.92rem/1.45 var(--font-serif);
  text-align: center;
}
.lvd-transcript {
  display: grid;
  gap: 0.6rem;
  max-height: 14rem;
  margin: 0;
  padding: 0;
  overflow: auto;
  list-style: none;
  font: 400 0.9rem/1.45 var(--font-serif);
}
.lvd-transcript li[data-role="user"] {
  color: var(--color-ink-light);
  font-family: var(--font-sans);
  font-size: 0.8rem;
}
.lvd-link {
  align-self: center;
  color: var(--color-ink-muted);
  font: 400 0.65rem/1 var(--font-typewriter);
  letter-spacing: 0.12em;
  text-transform: uppercase;
  text-decoration: underline;
  text-underline-offset: 3px;
}
.lvd-link:hover {
  color: var(--color-ink);
}
.lvd-notice {
  margin: 0;
  padding: 0.55rem 0.75rem;
  background: var(--lvd-tint);
  border-radius: 8px;
  line-height: 1.45;
}
.lvd-edit {
  padding: 0.75rem 0.85rem;
  background: var(--color-paper-soft, var(--color-paper));
  border: 1px solid color-mix(in srgb, var(--pp-color) 40%, var(--color-paper-3));
  border-radius: 12px;
}
.lvd-edit-kicker {
  margin: 0 0 0.4rem;
  color: color-mix(in srgb, var(--pp-color) 65%, var(--color-ink));
  font: 400 0.62rem/1 var(--font-typewriter);
  letter-spacing: 0.14em;
  text-transform: uppercase;
}
.lvd-edit del,
.lvd-edit ins {
  display: block;
  max-height: 9rem;
  margin: 0.35rem 0;
  overflow: auto;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  font: 400 0.95rem/1.45 var(--font-serif);
}
.lvd-edit del {
  color: var(--color-ink-muted);
}
.lvd-edit ins {
  text-decoration: none;
  font-weight: 600;
}
.lvd-edit-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.45rem;
  margin-top: 0.6rem;
}
.lvd-edit-actions > span {
  color: var(--color-ink-muted);
  font: italic 400 0.82rem/1 var(--font-serif);
}
.lvd-pill {
  padding: 0.45rem 0.85rem;
  border: 1px solid var(--color-ink-muted);
  border-radius: 999px;
  font-size: 0.78rem;
  font-weight: 600;
}
.lvd-pill--solid {
  color: var(--color-paper);
  background: var(--color-ink);
  border-color: var(--color-ink);
}
.lvd-sources {
  display: grid;
  gap: 0.6rem;
  margin: 0;
  padding: 0;
  list-style: none;
}
.lvd-sources a {
  font-weight: 600;
}
.lvd-sources p {
  margin: 0.2rem 0 0;
  color: var(--color-ink-light);
  font: 400 0.85rem/1.4 var(--font-serif);
}
.lvd-error {
  margin: 0;
  color: var(--color-vermilion);
  line-height: 1.45;
}

/* Credit and consent: one sentence, the fine print folded under it. */
.lvd-gate {
  display: grid;
  gap: 0.5rem;
  color: var(--color-ink-light);
  font-size: 0.8rem;
  line-height: 1.45;
  text-align: center;
}
.lvd-gate p {
  margin: 0;
}
.lvd-consent {
  display: flex;
  align-items: flex-start;
  gap: 0.55rem;
  text-align: left;
}
.lvd-consent input {
  margin-top: 0.2rem;
  accent-color: var(--pp-color);
}
.lvd-fine summary {
  cursor: pointer;
  color: var(--color-ink-muted);
  font-size: 0.72rem;
  list-style: none;
}
.lvd-fine summary::-webkit-details-marker {
  display: none;
}
.lvd-fine p {
  margin-top: 0.4rem;
  color: var(--color-ink-muted);
  font-size: 0.72rem;
  text-align: left;
}
.live-voice-desk a {
  text-decoration: underline;
  text-underline-offset: 3px;
}

/* ── Controls: one big button before, two round ones during ─ */
.lvd-controls {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 0.75rem;
  padding: 0.85rem 1.1rem 1.1rem;
}
.lvd-start {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.55rem;
  width: 100%;
  min-height: 3rem;
  color: var(--color-paper);
  background: color-mix(in srgb, var(--pp-color) 80%, var(--color-ink));
  border-radius: 999px;
  font-size: 0.95rem;
  font-weight: 600;
  transition:
    background 160ms ease,
    transform 120ms ease;
}
.lvd-start:not(:disabled):hover {
  background: color-mix(in srgb, var(--pp-color) 60%, var(--color-ink));
}
.lvd-start:not(:disabled):active {
  transform: scale(0.98);
}
.lvd-round {
  position: relative;
  display: grid;
  place-items: center;
  width: 3.1rem;
  height: 3.1rem;
  border-radius: 50%;
  color: var(--color-ink);
  background: var(--color-paper-2);
}
.lvd-round:hover:not(:disabled) {
  background: var(--color-paper-3);
}
.lvd-round[aria-pressed="true"] {
  color: var(--color-paper);
  background: var(--color-ink);
}
.lvd-slash {
  position: absolute;
  width: 2px;
  height: 1.6rem;
  background: currentColor;
  border-radius: 1px;
  rotate: -45deg;
}
.lvd-end {
  min-width: 6.5rem;
  height: 3.1rem;
  padding: 0 1.3rem;
  color: #fff;
  background: var(--color-accent-red, #b3261e);
  border-radius: 999px;
  font-size: 0.9rem;
  font-weight: 600;
}
.lvd-end:hover:not(:disabled) {
  filter: brightness(1.08);
}

.live-voice-desk button:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}
.live-voice-desk :focus-visible {
  outline: 2px solid var(--pp-color, var(--color-vermilion));
  outline-offset: 3px;
}

/* ── Minimized: a floating face with its controls ────────── */
.live-voice-desk.is-compact {
  flex-direction: row;
  align-items: center;
  width: auto;
  border-radius: 999px;
}
.live-voice-desk.is-compact .lvd-bar {
  position: static;
  order: 3;
  padding: 0 0.5rem 0 0;
}
.live-voice-desk.is-compact .lvd-bar h2 {
  display: none;
}
.live-voice-desk.is-compact .lvd-stage {
  flex-direction: row;
  gap: 0.6rem;
  padding: 0.35rem 0.4rem 0.35rem 0.35rem;
  background: none;
  text-align: left;
}
.live-voice-desk.is-compact .lvd-face {
  padding: 6px;
}
.live-voice-desk.is-compact .lvd-status {
  max-width: 11rem;
  margin: 0;
  font-size: 0.82rem;
}
.live-voice-desk.is-compact .lvd-controls {
  padding: 0 0.25rem;
  gap: 0.4rem;
}
.live-voice-desk.is-compact .lvd-round,
.live-voice-desk.is-compact .lvd-end {
  width: 2.5rem;
  min-width: 0;
  height: 2.5rem;
  padding: 0;
  font-size: 0.72rem;
}
.live-voice-desk.is-compact .lvd-start {
  width: auto;
  min-height: 2.5rem;
  padding: 0 1rem;
  font-size: 0.8rem;
}

@keyframes lvd-blink {
  50% {
    opacity: 0.35;
  }
}
@keyframes lvd-breathe {
  50% {
    --mic-level: 0.6;
  }
}

@media (max-width: 480px) {
  .live-voice-desk {
    right: 0.5rem;
    bottom: 0.5rem;
    width: calc(100vw - 1rem);
    max-height: calc(100dvh - 1rem);
  }
}
@media (prefers-reduced-motion: reduce) {
  .live-voice-desk,
  .lvd-cast-pick,
  .lvd-start {
    transition: none;
  }
  .live-voice-desk .lvd-live-dot,
  .live-voice-desk .lvd-halo {
    animation: none;
  }
}

